import{i as e}from"./index-CJ8x0t32.js";var t=e({food:()=>n}),n={ipoh:{eateries:[{id:`lou-wong`,name:`Restoran Tauge Ayam Lou Wong`,localName:`老黄芽菜鸡沙河粉`,area:`Jalan Yau Tet Shin, New Town`,lat:4.59423,lng:101.08348,kind:`casual`,meals:[`lunch`,`dinner`],spend:[20,45],order:[{name:`Bean sprout chicken`,localName:`芽菜鸡`,note:`Poached chicken with soy and sesame oil, priced by portion`,wiki:`Bean sprouts chicken`},{name:`Ipoh bean sprouts`,localName:`芽菜`,price:6,note:`Short, fat local bean sprouts blanched and dressed with soy and oil`},{name:`Kai si hor fun`,localName:`鸡丝河粉`,price:3,note:`Small bowl of smooth flat rice noodles in clear chicken broth`,wiki:`Shahe fen`}],why:`The best-known of the bean-sprout chicken shops on Jalan Yau Tet Shin, serving Ipoh's signature dish in a busy open-fronted hall.`,tip:`Chicken comes by the quarter, half or whole bird; order sprouts and noodles separately. Mid-afternoon is quietest.`,praise:[`Silky, tender poached chicken`,`Crunchy, sweet local bean sprouts`,`Fast turnover even when full`],watchOut:`Very busy with tour groups at peak times, and service is brisk rather than friendly.`,reservation:`walk-in`,reservationNote:`No bookings; wait for a table and staff will seat you quickly`},{id:`ipoh-tuck-kee`,name:`Ipoh Tuck Kee Restaurant`,localName:`怡保德记`,area:`Jalan Yau Tet Shin, New Town`,lat:4.5945,lng:101.08383,kind:`casual`,meals:[`lunch`,`dinner`],spend:[10,25],order:[{name:`Yu kong hor (moonlight hor fun)`,localName:`月光河`,price:10,note:`Wok-fried flat noodles in gravy topped with a raw egg to stir through`},{name:`Fried yee mee`,localName:`炒伊面`,price:10,note:`Springy egg noodles wok-fried with seafood and gravy`,wiki:`Yi mein`},{name:`Fried fish balls`,price:8,note:`Bouncy fish balls deep-fried golden`,wiki:`Fish ball`}],why:`A no-frills Cantonese noodle shop running since 1963, famous for its smoky moonlight hor fun cooked in a fierce wok.`,tip:`Do not confuse it with the similarly named shop next door; stir the raw egg into the noodles straight away.`,praise:[`Smoky wok-fried noodles`,`Generous plates at low prices`,`Old-school kopitiam feel`],reservation:`walk-in`,reservationNote:`No bookings; share a table at busy times`},{id:`nam-heong`,name:`Nam Heong`,localName:`南香`,area:`Jalan Bandar Timah, Old Town`,lat:4.59319,lng:101.07712,kind:`cafe`,meals:[`breakfast`,`lunch`],spend:[8,20],order:[{name:`Ipoh white coffee`,localName:`白咖啡`,price:3,note:`Margarine-roasted coffee served sweet with condensed milk`,wiki:`Ipoh white coffee`},{name:`Egg tart`,localName:`蛋挞`,price:2,note:`Flaky pastry case with a just-set, wobbly egg custard`,wiki:`Egg tart`},{name:`Curry mee`,localName:`咖喱面`,price:8,note:`Noodles in a spicy coconut curry broth from a stall inside`,wiki:`Curry mee`}],why:`One of the Old Town's classic white coffee houses, with hawker stalls inside and egg tarts that draw queues in the morning.`,tip:`Order coffee from the shop and food from the individual stalls; come early before the egg tarts sell out.`,praise:[`Rich, smooth white coffee`,`Flaky, freshly baked egg tarts`,`Lively old-school kopitiam buzz`],reservation:`walk-in`,reservationNote:`No bookings; grab any free seat and order at your table`},{id:`thean-chun`,name:`Thean Chun`,localName:`天津茶室`,area:`Jalan Bandar Timah, Old Town`,lat:4.59633,lng:101.07786,kind:`hawker`,meals:[`breakfast`,`lunch`],spend:[8,20],order:[{name:`Chicken hor fun`,localName:`鸡丝河粉`,price:8,note:`Smooth rice noodles in prawn-chicken broth with shredded chicken`,wiki:`Shahe fen`},{name:`Caramel custard`,localName:`焦糖布丁`,price:3,note:`Silky steamed custard with a bitter-sweet caramel top`,wiki:`Crème caramel`},{name:`Satay`,price:1,note:`Grilled skewers of meat with peanut sauce, priced per stick`,wiki:`Satay`}],why:`A high-ceilinged old coffee shop in the heritage quarter with several hawker stalls, known for chicken hor fun and its caramel custard.`,tip:`Go before noon; stalls close by early afternoon and the custard can sell out. Cash only.`,praise:[`Classic Ipoh hor fun in a heritage setting`,`Famous silky caramel custard`,`Plenty of choice from the stalls`],reservation:`walk-in`,reservationNote:`No bookings; sit anywhere and order from each stall`},{id:`funny-mountain`,name:`Funny Mountain Soya Bean`,localName:`奇峰豆腐花`,area:`Jalan Dato Tahwil Azar, New Town`,lat:4.59492,lng:101.08438,kind:`dessert`,meals:[`breakfast`,`lunch`],spend:[2,8],order:[{name:`Tau fu fa`,localName:`豆腐花`,price:2,note:`Silken soya pudding with sugar syrup, served warm or cold`,wiki:`Douhua`},{name:`Soya bean milk`,localName:`豆浆`,price:2,note:`Fresh, lightly sweetened soya milk, chilled or warm`,wiki:`Soy milk`}],why:`A decades-old shopfront where locals queue, drive up or eat on stools for some of Malaysia's smoothest tau fu fa.`,tip:`There is barely any seating; eat on the kerb like everyone else. It closes once sold out, often by late afternoon.`,praise:[`Exceptionally silky soya pudding`,`Very cheap`,`Quick-moving queue`],reservation:`walk-in`,reservationNote:`No bookings; order at the counter and eat standing or takeaway`},{id:`foh-san`,name:`Foh San`,localName:`富山茶楼`,area:`Jalan Leong Sin Nam, New Town`,lat:4.59682,lng:101.08601,kind:`restaurant`,meals:[`breakfast`,`lunch`],spend:[20,45],order:[{name:`Har gow`,localName:`虾饺`,price:6,note:`Translucent steamed dumplings packed with whole prawns`,wiki:`Har gow`},{name:`Siu mai`,localName:`烧卖`,price:5,note:`Open-topped pork and prawn dumplings`,wiki:`Shumai`},{name:`Lo mai gai`,localName:`糯米鸡`,price:7,note:`Sticky rice with chicken and mushroom steamed in a lotus leaf`,wiki:`Lo mai gai`}],why:`Ipoh's most famous dim sum house, a huge two-storey hall that has fed families since the 1960s, with dozens of items to pick from.`,tip:`Closed on Tuesdays. Arrive by 8am at weekends; the best items run out well before closing in the early afternoon.`,praise:[`Wide choice of freshly steamed dim sum`,`Classic bustling Ipoh breakfast scene`,`Good value for the quality`],watchOut:`Weekend mornings mean long waits for a table.`,reservation:`walk-in`,reservationNote:`No bookings; put your name down with staff and wait for a table`},{id:`yong-suan`,name:`Kedai Kopi Yong Suan`,area:`Jalan Yang Kalsom, New Town`,lat:4.59268,lng:101.08473,kind:`casual`,meals:[`lunch`],spend:[12,25],order:[{name:`Nasi ganja`,price:14,note:`Rice drenched in mixed curries with fried chicken, salted egg and cucumber`,wiki:`Nasi kandar`},{name:`Ayam merah`,price:8,note:`Fried chicken simmered in a sweet, spicy red chilli gravy`}],why:`The home of nasi ganja since 1957, an Indian-Muslim rice stall inside an old coffee shop whose curry-soaked plates draw queues daily.`,tip:`Open late morning to about 5pm on weekdays and 3pm at weekends; the queue looks long but moves quickly.`,praise:[`Deeply flavoured mix of curries`,`Crispy, well-spiced fried chicken`,`Generous plates for the price`],watchOut:`Expect a queue at lunchtime, and seating is cramped.`,reservation:`walk-in`,reservationNote:`No bookings; join the queue at the rice counter`},{id:`tong-sui-kai`,name:`Tong Sui Kai`,localName:`糖水街`,area:`Jalan Sultan Ekram, New Town`,lat:4.59573,lng:101.08727,kind:`hawker`,meals:[`dinner`,`late`],spend:[10,30],order:[{name:`Tong sui sweet soups`,localName:`糖水`,price:4,note:`Hot or cold Cantonese sweet soups with beans, sago or barley`,wiki:`Tong sui`},{name:`Char kway teow`,localName:`炒粿条`,price:9,note:`Flat rice noodles wok-fried with prawns, egg and bean sprouts`,wiki:`Char kway teow`},{name:`Satay`,price:1,note:`Charcoal-grilled skewers with peanut sauce, priced per stick`,wiki:`Satay`}],why:`An evening hawker lane of around fifty stalls, the place locals go for supper, from noodles and satay to bowls of sweet soup.`,tip:`Stalls open from about 5pm and run late; most are non-halal. Bring small notes.`,praise:[`Huge variety of hawker food in one lane`,`Great place for supper and desserts`,`Lively local evening atmosphere`],reservation:`walk-in`,reservationNote:`No bookings; grab a free table and order from any stall`}],dishes:{"Bean Sprout Chicken":{price:[15,35],wiki:`Bean sprouts chicken`},"Kai Si Hor Fun":{price:[7,12],wiki:`Shahe fen`},"Ipoh White Coffee":{price:[2.5,5],wiki:`Ipoh white coffee`},"Tau Fu Fa":{price:[2,4],wiki:`Douhua`},"Ipoh Dim Sum":{price:[4,12],wiki:`Dim sum`},"Nasi Ganja":{price:[10,20],wiki:`Nasi kandar`}}}},r=e({food:()=>i}),i={"johor-bahru":{eateries:[{id:`hua-mui`,name:`Restoran Hua Mui`,localName:`華美茶餐室`,area:`Jalan Trus, Old Town`,lat:1.45737,lng:103.76428,kind:`cafe`,meals:[`breakfast`,`lunch`],spend:[12,30],order:[{name:`Hainanese fried chicken chop`,price:22,note:`Breaded fried chicken thigh in brown gravy with fries and vegetables`,wiki:`Chicken chop`},{name:`Hainan fried mee`,price:12,note:`Yellow noodles fried Hainanese style in a savoury sauce`},{name:`Kaya butter toast`,note:`Toast with coconut kaya jam and butter`,wiki:`Kaya toast`}],why:`Hainanese coffee shop on Jalan Trus since 1946, known for its biscuit-crumbed chicken chop in brown gravy and kopitiam toast.`,tip:`The original branch fills up at lunch; come mid-morning. Pork-free, but check halal status if it matters to you.`,praise:[`Crisp chicken chop in brown gravy`,`Old-school Hainanese kopitiam feel`,`Classic kopi and toast`],reservation:`walk-in`,reservationNote:`No bookings; walk in and take a table, sharing at busy times`},{id:`hiap-joo-bakery`,name:`Hiap Joo Bakery & Biscuit Factory`,localName:`協裕麵包西果廠`,area:`Jalan Tan Hiok Nee, Old Town`,lat:1.45667,lng:103.76436,kind:`bakery`,meals:[`breakfast`],spend:[5,15],order:[{name:`Banana cake (box of 10 slices)`,price:13,note:`Dense, moist cake made with ripe bananas`,wiki:`Banana cake`},{name:`Otak-otak buns (2)`,price:5,note:`Soft buns filled with spicy fish paste`},{name:`Coconut buns (4)`,price:5,note:`Soft buns filled with sweet grated coconut`}],why:`Family bakery since 1919 still baking in a wood-fired oven; its moist banana cake is a JB souvenir in its own right.`,tip:`Mornings only in practice: things sell out early, banana cake is baked on set days, and Sunday hours are short.`,praise:[`Moist, fragrant banana cake`,`Wood-fired oven tradition`,`Good, inexpensive souvenirs`],reservation:`walk-in`,reservationNote:`No bookings; it is a takeaway counter, so just turn up early in the day`},{id:`kam-long-curry-fish-head`,name:`Kam Long Ah Zai Curry Fish Head`,localName:`金龍咖哩魚頭`,area:`Jalan Wong Ah Fook`,lat:1.45925,lng:103.76487,kind:`casual`,meals:[`breakfast`,`lunch`],spend:[20,45],order:[{name:`Curry fish head (small, for 2)`,note:`Fish head stewed in a spicy, sour curry with tofu puffs and vegetables`,wiki:`Fish head curry`},{name:`Steamed rice`,price:2,note:`Plain white rice to go with the curry`}],why:`Open-front shop near City Square serving a tangy, rich curry fish head with tofu puffs and vegetables since the 1980s.`,tip:`Opens 8am and closes when the curry runs out, usually mid-afternoon; expect a queue and a weekly rest day.`,praise:[`Rich, tangy curry gravy`,`Fresh fish head`,`Generous portions for sharing`],reservation:`walk-in`,reservationNote:`No bookings; join the queue and wait to be seated`},{id:`kacang-pool-haji`,name:`Restoran Kacang Pool Haji`,area:`Jalan Sabar, Larkin`,lat:1.49054,lng:103.75136,kind:`casual`,meals:[`breakfast`,`lunch`,`dinner`,`late`],spend:[7,18],order:[{name:`Kacang pool with beef`,price:7,note:`Mashed fava-bean stew with minced beef, topped with egg and served with bread`},{name:`Kacang pool with mutton`,price:11,note:`The same bean stew made with mutton`},{name:`Lontong`,price:7,note:`Rice cakes in a coconut vegetable curry`,wiki:`Lontong`}],why:`The best-known name for kacang pool in JB, ladling out the spiced bean stew with egg and toasted bread from early to late.`,tip:`Open roughly 7am to midnight daily. Ask for extra bread to mop up the gravy.`,praise:[`Hearty, spiced bean stew`,`Good with toasted bread`,`Open long hours`],reservation:`walk-in`,reservationNote:`No bookings needed; walk in at any hour and take a table`},{id:`onn-kitchen`,name:`Onn Kitchen`,area:`Jalan Tarom, Kampung Bahru`,lat:1.47575,lng:103.74542,kind:`casual`,meals:[`breakfast`,`lunch`,`dinner`],spend:[6,15],order:[{name:`Roti canai`,price:2,note:`Flaky griddle-cooked flatbread with curry or dhal`,wiki:`Roti canai`},{name:`Lontong`,price:8,note:`Compressed rice cakes in a coconut vegetable curry`,wiki:`Lontong`},{name:`Nasi lemak with fried egg`,price:6,note:`Coconut rice with sambal, peanuts, anchovies and a fried egg`,wiki:`Nasi lemak`}],why:`Malay neighbourhood eatery in Kampung Bahru for flaky roti canai, lontong and nasi lemak at local prices.`,tip:`Closed on Fridays. Breakfast is the liveliest time to go.`,praise:[`Flaky, crispy roti canai`,`Local prices`,`Friendly neighbourhood feel`],reservation:`walk-in`,reservationNote:`No bookings needed; walk in and order`},{id:`pisang-goreng-mawar`,name:`Pisang Goreng Mawar`,area:`Jalan Sungai Chat`,lat:1.46204,lng:103.74193,kind:`street`,meals:[`lunch`],spend:[5,15],order:[{name:`Pisang goreng with sambal kicap`,localName:`Goreng pisang`,price:5,note:`Battered fried bananas served with a sweet soy and chilli dip`,wiki:`Pisang goreng`},{name:`Laksa Johor`,note:`Spaghetti in a thick fish-based coconut gravy, a Johor speciality`,wiki:`Laksa`}],why:`A Johor institution for hot, crisp banana fritters dipped JB-style in sweet soy-chilli sambal, plus Malay staples like Laksa Johor.`,tip:`Order at the counter and wait for your number; the fritters come out in batches through the afternoon.`,praise:[`Crispy banana fritters`,`Sweet-spicy soy-chilli dip`,`Cheap and fast snack`],reservation:`walk-in`,reservationNote:`No bookings; order at the counter and wait for your number`},{id:`ww-laksa-house`,name:`W.W. Laksa House`,localName:`水塘辣沙`,area:`Jalan Kolam Air`,lat:1.47148,lng:103.73655,kind:`casual`,meals:[`breakfast`,`lunch`],spend:[8,15],order:[{name:`Water Works laksa with cockles`,price:9,note:`Noodles in a coconut curry broth with tau pok, fish cake and cockles`,wiki:`Laksa`},{name:`Otak-otak`,note:`Spiced fish paste grilled in a leaf wrapper`,wiki:`Otak-otak`}],why:`One of JB's oldest laksa shops, serving a coconut curry laksa loaded with tau pok, fish cake and cockles in a no-frills shophouse.`,tip:`Mornings to about 3pm and it sells out; reported closed on Wednesdays. Parking is tight, so take a Grab.`,praise:[`Thick, flavourful coconut curry broth`,`Generous cockles`,`Old-school shophouse charm`],watchOut:`Can sell out, and it is not air-conditioned.`,reservation:`walk-in`,reservationNote:`No bookings; walk in and share a table if it is busy`},{id:`restoran-todak`,name:`Restoran Todak`,area:`Teluk Jawa, Masai`,lat:1.47793,lng:103.84305,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[60,150],order:[{name:`Garlic or chilli crab (priced by weight)`,note:`Crab stir-fried with garlic or in a sweet-spicy chilli sauce`},{name:`Steamed red grouper`,note:`Whole red grouper steamed with soy, ginger and spring onion`},{name:`Curry prawns`,note:`Prawns cooked in a spiced curry gravy`}],why:`Seafood platform on stilts over the water in a fishing kampung, cooking crab, fish and prawns picked by weight with views to Singapore.`,tip:`There is no printed menu, so agree on prices by weight before cooking. Tables fill from 6pm at weekends.`,praise:[`Fresh seafood chosen from tanks`,`Breezy setting on stilts over the water`,`Views across to Singapore`],watchOut:`Prices by weight can surprise you; it is out of town, so plan transport back.`,reservation:`recommended`,reservationNote:`Walk-ins usually work; phone ahead for weekend dinners or large groups`}],dishes:{"Laksa Johor":{price:[8,15],wiki:`Laksa`},"Mee Rebus":{price:[6,12],wiki:`Mee rebus`},"Kacang Pool":{price:[7,12]},"Otak-Otak":{price:[3,10],wiki:`Otak-otak`},"Fish Head Curry":{price:[30,70],wiki:`Fish head curry`},"Hainanese Chicken Chop":{price:[16,25],wiki:`Chicken chop`}}}},a=e({food:()=>o}),o={"kota-kinabalu":{eateries:[{id:`yee-fung-laksa`,name:`Yee Fung Laksa`,localName:`Kedai Kopi Yee Fung`,area:`Gaya Street, City Centre`,lat:5.98233,lng:116.07647,kind:`casual`,meals:[`breakfast`,`lunch`],spend:[10,20],order:[{name:`Laksa`,price:11,note:`Rich, spicy coconut-curry noodle soup with prawns, chicken and tofu puffs`,wiki:`Laksa`},{name:`Ngiu chap`,price:13,note:`Beef noodles with brisket, tendon and beef balls in a spiced broth`,wiki:`Ngiu chap`},{name:`Kopi peng`,price:3,note:`Strong local iced coffee with condensed milk`,wiki:`Kopi`}],why:`A Gaya Street coffee shop that has drawn crowds for decades with its fragrant laksa and beefy ngiu chap, a classic KK breakfast stop.`,tip:`Opens early and closes by mid-afternoon; arrive before 9am or after the Sunday market rush to get a table.`,praise:[`Deep, aromatic laksa broth`,`Generous ngiu chap bowls`,`Fast service despite the crowds`],watchOut:`Tables fill fast at breakfast and you may share with strangers.`,reservation:`walk-in`,reservationNote:`No bookings; grab any free seat and order from the staff`},{id:`jia-siang-sang-nyuk-mee`,name:`Jia Siang Sang Nyuk Mee`,localName:`Kedai Kopi Jia Siang`,area:`Lintas Plaza, Luyang`,lat:5.94613,lng:116.0887,kind:`casual`,meals:[`breakfast`,`lunch`,`dinner`,`late`],spend:[10,18],order:[{name:`Sang nyuk mee, dry`,price:11,note:`Noodles tossed in dark soy and lard with a bowl of pork-slice soup on the side`,wiki:`Sang nyuk mee`},{name:`Sang nyuk mee, soup`,price:11,note:`Fresh pork, meatballs and offal with noodles in clear pork broth`,wiki:`Sang nyuk mee`}],why:`One of the best-known names for Sabah pork noodles, a Lintas coffee shop with famously long hours serving fresh pork in a sweet, clean broth.`,tip:`A Grab ride from the centre; handy for a late supper. Order dry noodles with the soup on the side, the local way.`,praise:[`Very fresh, tender pork`,`Clean, sweet pork broth`,`Open long hours, good for supper`],watchOut:`Pork dish, so not halal; out of the centre.`,reservation:`walk-in`,reservationNote:`No bookings; walk in and order at the table`},{id:`kah-hiong-ngiu-chap`,name:`Kah Hiong Ngiu Chap`,area:`Kolam Centre, Luyang`,lat:5.94883,lng:116.09183,kind:`casual`,meals:[`breakfast`,`lunch`],spend:[12,20],order:[{name:`Ngiu chap, soup`,price:14,note:`Beef brisket, tendon, tripe and beef balls in a herbal broth`,wiki:`Ngiu chap`},{name:`Ngiu chap, dry`,price:14,note:`Noodles tossed in soy sauce with the beef and broth served separately`,wiki:`Ngiu chap`}],why:`A Luyang favourite devoted to beef noodles, simmering brisket and daikon for hours with its own herb blend and serving a punchy house chilli.`,tip:`Mornings to about 3pm only. Try the house chilli sauce; bottles are sold at the counter.`,praise:[`Long-simmered, flavourful broth`,`Tender beef cuts`,`Excellent homemade chilli sauce`],reservation:`walk-in`,reservationNote:`No bookings; queue briefly at peak breakfast and lunch`},{id:`fook-yuen-gaya-street`,name:`Fook Yuen Café & Bakery`,area:`Gaya Street, City Centre`,lat:5.9851,lng:116.07801,kind:`cafe`,meals:[`breakfast`,`lunch`,`dinner`],spend:[6,15],order:[{name:`Kaya butter toast`,price:4,note:`Toasted bread with coconut jam and butter`,wiki:`Kaya toast`},{name:`Teh tarik`,price:3,note:`Sweet milky tea pulled until frothy`,wiki:`Teh tarik`},{name:`Roti bakar with half-boiled eggs`,price:6,note:`Toast with soft eggs seasoned with soy and pepper`}],why:`A bustling local café-bakery at the top of Gaya Street, the easy choice for toast, pastries and pulled tea from early morning into the evening.`,tip:`Order and pay at the counter, then find a table; pastries sell out through the day, so come early for the best choice.`,praise:[`Cheap, quick local breakfast`,`Good pulled tea and toast`,`Central and open long hours`],watchOut:`Busy, noisy and self-service.`,reservation:`walk-in`,reservationNote:`No bookings; order at the counter and take any free table`},{id:`yu-kee-bak-kut-teh`,name:`Yu Kee Bak Kut Teh`,area:`Gaya Street, City Centre`,lat:5.9848,lng:116.07752,kind:`casual`,meals:[`dinner`],spend:[25,45],order:[{name:`Bak kut teh with mixed cuts`,price:22,note:`Pork ribs and cuts simmered in a peppery herbal soup`,wiki:`Bak kut teh`},{name:`Fried dough sticks`,price:3,note:`Crisp Chinese crullers for dunking in the soup`,wiki:`Youtiao`},{name:`Braised pork leg`,price:15,note:`Soy-braised pork leg, soft and sticky`}],why:`KK’s most famous bak kut teh shop, ladling claypots of herbal pork soup to packed pavement tables every evening.`,tip:`Opens late afternoon; arrive before 6pm or expect to wait. Popular cuts can sell out later in the evening.`,praise:[`Fragrant, peppery herbal soup`,`Tender pork ribs`,`Lively evening atmosphere`],watchOut:`Queues after office hours; pork, so not halal.`,reservation:`walk-in`,reservationNote:`No bookings; join the queue and staff will seat you`},{id:`welcome-seafood-restaurant`,name:`Welcome Seafood Restaurant`,area:`Asia City`,lat:5.97485,lng:116.07293,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[50,120],order:[{name:`Butter prawns`,price:40,note:`Prawns fried with butter, curry leaves and egg floss`},{name:`Steamed grouper`,price:70,note:`Live fish from the tanks, steamed Hong Kong style with soy and ginger`},{name:`Stir-fried sayur manis`,price:15,note:`Sabah’s sweet leaf vegetable wok-fried with garlic or egg`}],why:`A huge, always-busy seafood hall where you pick live fish, crab, lobster and clams from the tanks at fair prices, a long-time KK institution.`,tip:`Seafood is priced by weight; confirm the price before cooking. Go early evening to beat the dinner crush.`,praise:[`Very fresh seafood from live tanks`,`Good value for seafood`,`Wide choice of cooking styles`],watchOut:`Loud, crowded and functional rather than pretty.`,reservation:`recommended`,reservationNote:`Walk-ins usually fine; phone ahead for weekend dinners or big groups`},{id:`kk-night-market-grill`,name:`Waterfront Night Market Seafood Grills`,localName:`Pasar Malam Kota Kinabalu`,area:`Waterfront`,lat:5.98109,lng:116.07134,kind:`market`,meals:[`dinner`],spend:[20,60],order:[{name:`Grilled fish`,note:`Whole fish of your choice grilled over charcoal with sambal`,wiki:`Ikan bakar`},{name:`Grilled squid`,price:15,note:`Fresh squid grilled with a sweet chilli glaze`,wiki:`Squid as food`},{name:`Grilled chicken wings`,price:3,note:`Charcoal-grilled wings sold by the piece`}],why:`The city’s nightly seafront feast: choose seafood from iced displays and have it grilled on the spot, eaten at long tables by the sea.`,tip:`Agree price and weight before cooking; carry cash and wet wipes. Stalls light up from late afternoon.`,praise:[`Fresh seafood at low prices`,`Lively, smoky seaside scene`,`Huge choice in one place`],watchOut:`Prices vary by stall and some quote high for tourists; check before ordering.`,reservation:`walk-in`,reservationNote:`Market stalls: no bookings; choose, pay and sit at shared tables`},{id:`fatt-kee`,name:`Kedai Kopi Fatt Kee`,area:`Jalan Haji Saman, City Centre`,lat:5.98491,lng:116.07648,kind:`casual`,meals:[`lunch`,`dinner`],spend:[20,40],order:[{name:`Oyster sauce chicken wings`,price:15,note:`Wings fried and glazed in a sticky oyster sauce`},{name:`Sweet and sour prawns`,price:30,note:`Crisp prawns in a tangy tomato-based sauce`},{name:`Hokkien mee`,price:12,note:`Thick noodles fried in dark soy with pork and crispy lard`,wiki:`Hokkien mee`}],why:`A no-frills Chinese coffee shop in the old centre, long loved for hearty, well-priced wok dishes; its glazed chicken wings are the signature.`,tip:`Go at opening time for lunch or dinner, as tables fill fast; dishes come in small, medium and large sizes for sharing.`,praise:[`Signature chicken wings`,`Big flavours at fair prices`,`Quick wok-fried classics`],watchOut:`Some dishes run salty or sweet; basic coffee-shop setting.`,reservation:`walk-in`,reservationNote:`No bookings; arrive early at meal times to get a table`}],dishes:{"Tuaran Mee":{price:[10,16],wiki:`Tuaran mee`},"Sang Nyuk Mee":{price:[9,15],wiki:`Sang nyuk mee`},"Ngiu Chap":{price:[11,18],wiki:`Ngiu chap`},Hinava:{price:[8,20],wiki:`Hinava`},"Ikan Bakar":{price:[15,60],wiki:`Ikan bakar`},"Bak Kut Teh":{price:[18,32],wiki:`Bak kut teh`}}}},s=e({food:()=>c}),c={kuching:{eateries:[{id:`choon-hui-cafe`,name:`Choon Hui Café`,localName:`Kedai Kopi Choon Hui`,area:`Jalan Ban Hock`,lat:1.55493,lng:110.35232,kind:`casual`,meals:[`breakfast`,`lunch`],spend:[10,20],order:[{name:`Sarawak laksa`,price:12,note:`Sambal-and-coconut broth with prawns, chicken and omelette strips`,wiki:`Sarawak laksa`},{name:`Teh C peng special`,price:4,note:`Three-layer iced tea with palm sugar and evaporated milk`}],why:`A no-frills corner coffee shop whose laksa stall became world-famous after a celebrity chef visit, still one of the benchmarks for a rich, prawn-laden bowl.`,tip:`Opens early and usually closes by early afternoon; closed one weekday, typically Monday. Arrive before 8am at weekends.`,praise:[`Rich, fragrant laksa broth`,`Plump fresh prawns`,`Authentic old kopitiam setting`],watchOut:`Long waits for the laksa at weekends and holidays; it can sell out.`,reservation:`walk-in`,reservationNote:`No bookings; find a seat, then order at the laksa stall`},{id:`chong-choon-cafe`,name:`Chong Choon Café`,area:`Jalan Abell`,lat:1.55604,lng:110.35694,kind:`casual`,meals:[`breakfast`,`lunch`],spend:[10,18],order:[{name:`Sarawak laksa`,price:11,note:`Pork-free laksa with prawns and chicken in a punchy spiced broth`,wiki:`Sarawak laksa`},{name:`Kopi C`,price:3,note:`Strong local coffee with evaporated milk`}],why:`A long-running laksa specialist loved for a spicy, aromatic broth with no pork, which draws a mixed local crowd from early morning.`,tip:`Mornings only, from about 6.30am until the laksa runs out around noon.`,praise:[`Bold, spice-packed broth`,`Pork-free, so suits more diners`,`Efficient despite the queue`],watchOut:`Morning-only and very crowded on weekends.`,reservation:`walk-in`,reservationNote:`No bookings; queue at the laksa stall`},{id:`hon-hin-cafe`,name:`Hon Hin Café`,area:`Jalan Tunku Abdul Rahman`,lat:1.55923,lng:110.35371,kind:`casual`,meals:[`breakfast`,`lunch`],spend:[6,14],order:[{name:`Kolo mee`,price:6,note:`Springy noodles in shallot oil with char siu and minced pork`,wiki:`Kolo mee`},{name:`Braised egg and dumplings`,note:`Soy-braised egg and pork dumplings to add on`}],why:`An early-opening coffee shop near the waterfront hotels, popular for classic kolo mee and braised add-ons at local prices.`,tip:`Order kolo mee "red" if you like it sweeter with char siu sauce; best before mid-morning.`,praise:[`Springy, well-seasoned noodles`,`Very cheap`,`Close to the riverside hotels`],watchOut:`Pork dishes, so not halal; busy at breakfast.`,reservation:`walk-in`,reservationNote:`No bookings; grab a table and order from the stall`},{id:`lau-ya-keng-food-court`,name:`Lau Ya Keng Food Court`,area:`Carpenter Street, Old Town`,lat:1.55787,lng:110.34636,kind:`hawker`,meals:[`breakfast`,`lunch`],spend:[6,15],order:[{name:`Sarawak laksa`,price:9,note:`Laksa from the popular stall at the front, with toppings to choose`,wiki:`Sarawak laksa`},{name:`Kolo mee`,price:6,note:`Dry-tossed egg noodles with char siu`,wiki:`Kolo mee`},{name:`Popiah`,note:`Fresh spring roll stuffed with turnip, egg and peanuts`,wiki:`Popiah`}],why:`An open-air hawker court facing a Chinese temple on Carpenter Street, the easiest place in the old town to try laksa, kolo mee and more at one table.`,tip:`Mornings are best; several stalls close by early afternoon.`,praise:[`Lots of choice in one spot`,`Atmospheric temple-side setting`,`Friendly to first-timers`],watchOut:`Hot and basic, with no air-con.`,reservation:`walk-in`,reservationNote:`Hawker centre; take any table and order at the stalls`},{id:`top-spot-food-court`,name:`Top Spot Food Court`,area:`Jalan Bukit Mata, City Centre`,lat:1.55745,lng:110.35185,kind:`hawker`,meals:[`dinner`,`late`],spend:[50,120],order:[{name:`Midin belacan`,price:15,note:`Jungle fern shoots stir-fried with shrimp paste`,wiki:`Midin`},{name:`Butter prawns or salted-egg crab`,note:`Seafood cooked to order from the tanks, priced by weight`},{name:`Steamed fish`,note:`Choose a live fish and a style: ginger-soy, Teochew or sweet-sour`}],why:`A rooftop seafood court atop a car park, where rival stalls display live fish and shellfish to be cooked to order, Kuching's classic night-out feast.`,tip:`Ling Loong and a couple of other long-standing stalls are favourites; ask the price per kilo before choosing seafood.`,praise:[`Huge choice of fresh seafood`,`Lively open-air atmosphere`,`Good midin and fried dishes`],watchOut:`Seafood priced by weight can add up quickly; confirm prices first.`,reservation:`walk-in`,reservationNote:`No bookings; pick a stall, order and take a nearby table`},{id:`lepau-restaurant`,name:`Lepau Restaurant`,area:`Jalan Ban Hock`,lat:1.55383,lng:110.35492,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[35,80],order:[{name:`Manok pansoh`,price:30,note:`Chicken cooked in bamboo with lemongrass, ginger and tapioca leaves`,wiki:`Ayam pansuh`},{name:`Midin belacan`,price:16,note:`Jungle fern stir-fried with house shrimp paste`,wiki:`Midin`},{name:`Ikan terubok masin`,note:`Salted shad, a Sarawak delicacy, grilled or fried`}],why:`A rustic, longhouse-styled restaurant that brought Dayak home cooking to a wider audience, serving bamboo-cooked chicken and foraged jungle greens.`,tip:`Order a few small plates to share; ask staff to explain the indigenous ingredients and rice wine.`,praise:[`Rare chance to taste Dayak dishes`,`Warm, rustic setting`,`Helpful staff explain the menu`],watchOut:`Portions can be small for the price.`,reservation:`recommended`,reservationNote:`Book for weekend dinners or groups; walk-ins usually fine at lunch`},{id:`james-brooke-bistro`,name:`James Brooke Bistro & Café`,area:`Waterfront`,lat:1.55951,lng:110.35017,kind:`casual`,meals:[`lunch`,`dinner`],spend:[25,60],order:[{name:`Wild Borneo laksa`,price:15,note:`The house twist on laksa with a creamier, spicier broth`},{name:`Sarawak laksa`,price:15,note:`The classic version, for comparison`,wiki:`Sarawak laksa`}],why:`An open-air bistro right on the waterfront with river views to the fort and assembly building, a relaxed spot for laksa or dinner at sunset.`,tip:`Grab a riverside table before sunset; afternoons can be hot as there is no air-con.`,praise:[`Lovely river views`,`Inventive house laksa`,`Relaxed, friendly service`],watchOut:`No air-conditioning, and prices are higher than coffee shops.`,reservation:`walk-in`,reservationNote:`Usually walk-in; phone ahead for a sunset table for larger groups`},{id:`mira-cake-house`,name:`Mira Cake House`,area:`Kampung Gersik, North Bank`,lat:1.56328,lng:110.34182,kind:`bakery`,meals:[`breakfast`,`lunch`],spend:[15,60],order:[{name:`Kek lapis Sarawak`,price:35,note:`Patterned butter layer cake, sold by the bar in many flavours`,wiki:`Sarawak layer cake`},{name:`Kek lapis tasting slices`,note:`Free samples to try flavours like pandan, prune or cheese before buying`}],why:`A well-known Malay family layer-cake maker across the river, baking dozens of colourful kek lapis flavours to sample and take home.`,tip:`Take a sampan across the river and walk through the kampung; cakes keep for days, so they travel well.`,praise:[`Generous tasting before you buy`,`Huge range of flavours`,`Good-value gifts`],reservation:`walk-in`,reservationNote:`Walk in to taste and buy; large orders can be placed ahead`}],dishes:{"Sarawak laksa":{price:[9,16],wiki:`Sarawak laksa`},"Kolo mee":{price:[5,9],wiki:`Kolo mee`},"Manok pansoh":{price:[25,45],wiki:`Ayam pansuh`},"Midin belacan":{price:[12,22],wiki:`Midin`},"Kek lapis Sarawak":{price:[20,60],wiki:`Sarawak layer cake`},"Teh C peng special":{price:[3,5]}}}},l=e({food:()=>u}),u={langkawi:{eateries:[{id:`siti-fatimah`,name:`Restoran Siti Fatimah`,area:`Kampung Tok Senik, Jalan Mata Ayer`,lat:6.32721,lng:99.78285,kind:`casual`,meals:[`breakfast`,`lunch`],spend:[10,20],order:[{name:`Nasi campur with curries, fried fish and ulam`,price:12,note:`Rice with your pick of curries, fried fish and raw herbs from the buffet`,wiki:`Nasi campur`},{name:`Asam pedas fish`,price:10,note:`Fish in a sour, spicy tamarind and chilli gravy`,wiki:`Asam pedas`},{name:`Teh tarik`,price:2,note:`Sweet milky tea pulled until frothy`,wiki:`Teh tarik`}],why:`Langkawi’s best-known Malay rice buffet, a village restaurant laying out dozens of home-style curries, sambals and fried fish every day.`,tip:`Arrive late morning for the fullest spread; it closes mid-afternoon and some sources list Wednesday as a day off.`,praise:[`Huge spread of home-style Malay dishes`,`Good fried fish and sambals`,`Very fair prices`],reservation:`walk-in`,reservationNote:`No bookings; help yourself at the buffet, then pay at the counter`},{id:`nasi-kandar-tomato`,name:`Restoran Nasi Kandar Tomato`,area:`Pantai Cenang / Pantai Tengah`,lat:6.28499,lng:99.73233,kind:`casual`,meals:[`breakfast`,`lunch`,`dinner`,`late`],spend:[8,20],order:[{name:`Roti canai with dhal`,localName:`Roti canai`,price:2,note:`Flaky fried flatbread served with lentil curry`,wiki:`Roti canai`},{name:`Nasi kandar with fried chicken`,price:13,note:`Rice with fried chicken and mixed curry gravies`,wiki:`Nasi kandar`},{name:`Teh tarik`,price:3,note:`Sweet milky tea pulled until frothy`,wiki:`Teh tarik`}],why:`Big, open-sided round-the-clock mamak at the south end of the Cenang strip, serving roti, nasi kandar and noodles at local prices.`,tip:`Busy and sometimes slow at peak dinner time; order at the counter for nasi kandar.`,praise:[`Open round the clock`,`Cheap, filling food near the beach`,`Good roti canai`],reservation:`walk-in`,reservationNote:`No bookings; open round the clock, so just walk in`},{id:`laksa-power`,name:`Laksa Power`,area:`Jalan Kuala Muda (by the airport)`,lat:6.32448,lng:99.72254,kind:`street`,meals:[`lunch`],spend:[6,15],order:[{name:`Laksa Langkawi with kuah lemak`,price:6,note:`Rice noodles in a fish broth, here with a coconut-milk gravy`,wiki:`Laksa`},{name:`Rojak`,price:6,note:`Fruit and vegetables in a sweet, spicy sauce`,wiki:`Rojak`},{name:`Coconut shake`,price:6,note:`Fresh coconut blended into a cold drink`}],why:`Simple beachside stall beside the airport runway, ladling sour fish laksa you eat on plastic stools facing the sea while planes land.`,tip:`A good stop on the way to or from a flight; roadside hours vary, so go from late morning to mid-afternoon.`,praise:[`Unique view of planes landing over the sea`,`Tangy, flavourful laksa`,`Cheap and casual`],watchOut:`Basic plastic-stool seating outdoors, by the roadside.`,reservation:`walk-in`,reservationNote:`Roadside stall: no bookings; walk up and order`},{id:`red-tomato`,name:`Red Tomato`,area:`Pantai Cenang`,lat:6.2866,lng:99.73016,kind:`cafe`,meals:[`breakfast`,`lunch`],spend:[25,50],order:[{name:`Banana pancakes`,price:18,note:`Pancakes topped with sliced banana`},{name:`All-day breakfast`,price:28,note:`Eggs, bread and sides in a full breakfast plate`},{name:`Wood-fired pizza`,price:35,note:`Thin-crust pizza baked in a wood-fired oven`}],why:`Long-running courtyard café on the Cenang strip with home-baked bread, big Western breakfasts and pizzas; a reliable start to a beach day.`,tip:`Opposite Underwater World. Hours change seasonally, so check before heading over for an early breakfast.`,praise:[`Hearty Western breakfasts`,`Home-baked bread`,`Relaxed garden courtyard`],watchOut:`Pricier than local breakfast spots.`,reservation:`walk-in`,reservationNote:`No bookings needed; walk in and take a table in the courtyard`},{id:`wonderland-food-store`,name:`Wonderland Food Store`,area:`Persiaran Mutiara, Kuah`,lat:6.32465,lng:99.84388,kind:`casual`,meals:[`dinner`],spend:[40,90],order:[{name:`Kam heong prawns`,price:35,note:`Prawns wok-fried with curry leaves, dried shrimp and chilli`},{name:`Steamed fish, Teochew style`,price:50,note:`Whole fish steamed with pickled vegetables, tomato and plum`},{name:`Seafood fried rice`,price:15,note:`Wok-fried rice with prawns and squid`}],why:`Busy open-air Chinese seafood restaurant in Kuah town, a long-time local favourite for wok-fried prawns, crab and fish at fair prices.`,tip:`Dinner only. Seafood is priced by weight, so confirm the price before it goes in the wok.`,praise:[`Fresh, well-cooked seafood`,`Good value for seafood`,`Popular with locals`],watchOut:`Busy and basic open-air setting; queues at peak dinner time.`,reservation:`walk-in`,reservationNote:`No bookings; turn up early in the evening to avoid the wait for a table`},{id:`orkid-ria`,name:`Orkid Ria Seafood Restaurant`,area:`Pantai Cenang`,lat:6.29569,lng:99.72374,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[50,120],order:[{name:`Chilli crab`,price:60,note:`Crab stir-fried in a sweet, savoury tomato-chilli sauce`,wiki:`Chilli crab`},{name:`Butter prawns`,price:40,note:`Prawns fried with butter, curry leaves and chilli`},{name:`Ikan bakar (grilled fish)`,price:40,note:`Fish marinated in spices and grilled over charcoal`,wiki:`Ikan bakar`}],why:`Established Chinese-style seafood house on the Cenang strip, picking live fish, crab and lobster from tanks to cook the way you like.`,tip:`Ask for the price per 100 g before choosing from the tanks; lobster adds up fast.`,praise:[`Fresh seafood picked live from tanks`,`Choice of cooking styles`,`Central Cenang location`],reservation:`recommended`,reservationNote:`Walk-ins usually fine; phone ahead for high-season dinners or groups`},{id:`the-cliff`,name:`The Cliff Restaurant & Bar`,area:`Pantai Cenang`,lat:6.28724,lng:99.72744,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[60,130],order:[{name:`Malay seafood curry`,price:55,note:`Seafood simmered in a Malay-style spiced curry`},{name:`Ikan bakar`,price:50,note:`Fish marinated in spices and grilled`,wiki:`Ikan bakar`},{name:`Sunset cocktail`,price:30,note:`A tropical cocktail to drink while the sun sets`}],why:`Open-sided restaurant perched on the rocky headland between Cenang and Tengah beaches, mixing Malay and international dishes with sea views.`,tip:`Book a railing table for sunset; it fills quickly in the high season (December to March).`,praise:[`Sunset views over the sea`,`Mix of Malay and Western dishes`,`Relaxed setting for drinks`],watchOut:`Prices reflect the view.`,reservation:`recommended`,reservationNote:`Book a day or two ahead for a sunset table; other times walk-ins usually work`},{id:`the-gulai-house`,name:`The Gulai House`,area:`The Datai, Datai Bay`,lat:6.42401,lng:99.67254,kind:`fine`,meals:[`dinner`],spend:[200,400],order:[{name:`Gulai ikan (fish curry)`,note:`Fish in a rich, turmeric-yellow curry gravy`,wiki:`Gulai`},{name:`Beef rendang`,note:`Beef slow-cooked in coconut milk and spices until dry and tender`,wiki:`Rendang`},{name:`Malay and Indian set menu`,note:`A set selection of the kitchen’s Malay and Indian dishes`}],why:`Refined Malay and Indian cooking in a kampung-style pavilion deep in the rainforest at The Datai, a special-occasion splurge.`,tip:`Reserve ahead and ask whether non-resident bookings are open; it is a 40-minute drive from Cenang.`,praise:[`Rainforest setting`,`Refined Malay and Indian flavours`,`Attentive resort service`],watchOut:`Expensive and remote; access may be limited for non-guests.`,reservation:`essential`,reservationNote:`Book ahead through The Datai; non-guests must confirm a table first`}],dishes:{"Laksa Langkawi":{price:[5,10],wiki:`Laksa`},"Nasi Campur":{price:[8,18],wiki:`Nasi campur`},"Ikan Bakar":{price:[15,60],wiki:`Ikan bakar`},"Asam Pedas":{price:[10,25],wiki:`Asam pedas`},"Roti Canai":{price:[1.5,4],wiki:`Roti canai`},Satay:{price:[6,15],wiki:`Satay`}}}},d=e({food:()=>f}),f={malacca:{eateries:[{id:`the-daily-fix`,name:`The Daily Fix Cafe`,area:`Jonker Street`,lat:2.19624,lng:102.24669,kind:`cafe`,meals:[`breakfast`,`lunch`],spend:[20,40],order:[{name:`Pandan pancakes with gula melaka`,price:15,note:`Green pandan-flavoured pancakes with gula melaka syrup`},{name:`Nyonya laksa`,note:`Noodles in a spicy coconut-curry broth, Nyonya style`,wiki:`Laksa`},{name:`Iced latte`,note:`Espresso and milk over ice`}],why:`Vintage-styled cafe hidden behind a souvenir shop on Jonker Street, known for bright green pandan pancakes and brunch plates.`,tip:`Opens around 9.45am; arrive at opening on weekends or expect a wait for a table.`,praise:[`Fluffy pandan pancakes with palm sugar syrup`,`Charming vintage interior`,`Good coffee`],reservation:`walk-in`,reservationNote:`No bookings; wait at the door for a table, shortest right at opening`},{id:`chung-wah-chicken-rice-ball`,name:`Kedai Kopi Chung Wah`,localName:`中华茶室`,area:`Jalan Hang Jebat, Jonker Street`,lat:2.195,lng:102.24844,kind:`casual`,meals:[`breakfast`,`lunch`],spend:[10,20],order:[{name:`Chicken rice balls (per ball)`,price:1,note:`Chicken-stock rice pressed into small balls`,wiki:`Hainanese chicken rice`},{name:`Poached chicken, half bird`,price:24,note:`Poached chicken with soy and chilli sauce`}],why:`Old corner coffee shop at the foot of Jonker Street that serves little more than poached chicken and pandan-scented rice balls.`,tip:`Closes mid-afternoon or when sold out; come before noon to beat the queue.`,praise:[`Tender, smooth poached chicken`,`Fragrant rice balls`,`Old Malacca character`],reservation:`walk-in`,reservationNote:`No bookings; join the queue and share a table`},{id:`jonker-88`,name:`Jonker 88`,area:`Jalan Hang Jebat, Jonker Street`,lat:2.19667,lng:102.24664,kind:`casual`,meals:[`lunch`],spend:[8,18],order:[{name:`Baba laksa`,price:9,note:`Nyonya noodles in a spicy coconut-curry broth`,wiki:`Laksa`},{name:`Gula melaka cendol`,price:5,note:`Shaved ice with green jelly, coconut milk and dark palm sugar syrup`,wiki:`Cendol`},{name:`Durian cendol`,price:8,note:`Cendol topped with durian pulp`,wiki:`Cendol`}],why:`Busy heritage-shophouse canteen for Nyonya laksa and cendol thick with dark gula melaka syrup, right on Jonker Street.`,tip:`Order and pay at the counters, then find your own seat; open later on Friday and Saturday nights.`,praise:[`Rich, thick baba laksa`,`Dark, generous gula melaka in the cendol`,`Heritage shophouse setting`],watchOut:`Crowded and hot at peak times.`,reservation:`walk-in`,reservationNote:`No bookings; order at the counters and find your own seat`},{id:`nancys-kitchen`,name:`Nancy's Kitchen`,area:`Kota Laksamana`,lat:2.19774,lng:102.23972,kind:`restaurant`,meals:[`lunch`],spend:[30,60],order:[{name:`Candlenut chicken`,note:`Chicken cooked in a thick, spiced gravy with ground candlenuts`},{name:`Ayam pongteh`,note:`Chicken and potato braised with fermented soybean paste and palm sugar`},{name:`Chap chye`,note:`Mixed vegetables braised in a savoury sauce`}],why:`Family-run Nyonya restaurant since 1999 cooking Peranakan home recipes passed down through generations.`,tip:`Mainly a lunch spot that closes early evening; book ahead at weekends.`,praise:[`Authentic home-style Nyonya dishes`,`Friendly family-run service`,`Rich candlenut chicken`],reservation:`recommended`,reservationNote:`Phone a day or two ahead for weekend lunch; weekday walk-ins usually work`},{id:`asam-pedas-selera-kampung`,name:`Asam Pedas Selera Kampung`,area:`Plaza Mahkota`,lat:2.18991,lng:102.24766,kind:`casual`,meals:[`lunch`],spend:[12,30],order:[{name:`Asam pedas ikan pari (stingray)`,note:`Stingray in a sour, spicy tamarind and chilli gravy`,wiki:`Asam pedas`},{name:`Asam pedas ikan tenggiri (mackerel)`,note:`Spanish mackerel in a sour, spicy tamarind and chilli gravy`,wiki:`Asam pedas`}],why:`Malay lunch spot near the old town serving Malacca-style asam pedas, sour and fiery, with a choice of fresh fish over rice.`,tip:`Gets packed at lunchtime; arrive before 12pm for the best choice of fish.`,praise:[`Sour, fiery asam pedas`,`Fresh fish choices`,`Homely Malay cooking`],reservation:`walk-in`,reservationNote:`No bookings; walk in and pick your fish at the counter`},{id:`capitol-satay-celup`,name:`Capitol Satay Celup`,localName:`国泰沙爹朱律`,area:`Lorong Bukit Cina`,lat:2.19528,lng:102.2523,kind:`casual`,meals:[`dinner`],spend:[25,45],order:[{name:`Satay celup skewers (per stick)`,price:1.5,note:`Skewered meat, seafood and vegetables dipped in a pot of hot peanut sauce`,wiki:`Satay celup`},{name:`Quail eggs and cockles`,note:`Popular skewer choices for dipping in the peanut sauce`}],why:`The best-known name for satay celup: pick skewers from the fridge and cook them in a shared pot of peanut sauce at your table.`,tip:`Evenings only and often a queue; you pay by counting your sticks at the end.`,praise:[`Fun cook-it-yourself experience`,`Rich, spicy peanut sauce`,`Wide choice of skewers`],watchOut:`Long evening queues, and the shop gets hot inside.`,reservation:`walk-in`,reservationNote:`No bookings; join the queue outside and wait to be seated`},{id:`ole-sayang`,name:`Restoran Ole Sayang`,area:`Taman Melaka Raya`,lat:2.18769,lng:102.25567,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[30,60],order:[{name:`Ayam pongteh`,note:`Chicken and potato braised with fermented soybean paste and palm sugar`},{name:`Udang lemak nenas (prawns in pineapple coconut curry)`,note:`Prawns cooked with pineapple in a spiced coconut curry`},{name:`Nyonya cendol`,note:`Shaved ice with green jelly, coconut milk and palm sugar`,wiki:`Cendol`}],why:`Old-school Nyonya dining room in Melaka Raya serving classic Peranakan dishes since the early 1980s, good for a sit-down family dinner.`,tip:`Open for lunch and dinner with a break mid-afternoon; usually closed on Wednesdays.`,praise:[`Classic Peranakan dishes`,`Traditional Nyonya decor`,`Good for family meals`],reservation:`recommended`,reservationNote:`Phone ahead for weekend or group dinners; weekday walk-ins are usually fine`},{id:`klebang-coconut-shake`,name:`Klebang Original Coconut Shake`,area:`Klebang`,lat:2.21578,lng:102.2069,kind:`dessert`,meals:[`lunch`],spend:[5,10],order:[{name:`Coconut shake with vanilla ice cream`,price:5,note:`Coconut water and flesh blended with vanilla ice cream`},{name:`Whole young coconut`,price:6,note:`Fresh young coconut to drink from`}],why:`Roadside stall that made the Klebang coconut shake famous: fresh coconut water and flesh blended with vanilla ice cream.`,tip:`Cash only; open late morning to early evening. Pair with sunset at Klebang Beach.`,praise:[`Creamy, refreshing coconut shake`,`Cheap`,`Fast service despite queues`],watchOut:`Queues build on hot afternoons and weekends.`,reservation:`walk-in`,reservationNote:`Roadside stall: no bookings; queue, order and drink on the spot`}],dishes:{"Chicken Rice Balls":{price:[10,20],wiki:`Hainanese chicken rice`},"Nyonya Laksa":{price:[8,15],wiki:`Laksa`},"Asam Pedas":{price:[12,30],wiki:`Asam pedas`},"Satay Celup":{price:[20,45],wiki:`Satay celup`},"Gula Melaka Cendol":{price:[4,8],wiki:`Cendol`},"Devil's Curry":{price:[15,30],wiki:`Devil's curry`}}}},p=e({food:()=>m}),m={"kuala-lumpur":{eateries:[{id:`village-park`,name:`Village Park Restaurant`,area:`Damansara Utama, Petaling Jaya`,lat:3.13776,lng:101.62339,kind:`casual`,meals:[`breakfast`,`lunch`],spend:[13,25],order:[{name:`Nasi lemak with spiced fried chicken`,localName:`Nasi lemak ayam goreng berempah`,price:13,note:`Coconut-milk rice with sambal, peanuts, anchovies, egg and spiced fried chicken`,wiki:`Nasi lemak`},{name:`Teh tarik`,price:3,note:`Sweet milky tea poured back and forth to make it frothy`,wiki:`Teh tarik`}],why:`Busy Damansara Uptown kopitiam whose nasi lemak with crisp spiced fried chicken has drawn crowds for over 20 years.`,tip:`Tables are hard to get at peak times; many locals take away.`,praise:[`Crunchy, well-spiced fried chicken`,`Fragrant coconut rice with good sambal`,`Fast turnover despite the crowds`],reservation:`walk-in`,reservationNote:`No bookings; wait for a table at peak times or order takeaway`},{id:`yut-kee`,name:`Yut Kee`,localName:`日记`,area:`Chow Kit`,lat:3.15648,lng:101.7003,kind:`casual`,meals:[`breakfast`,`lunch`],spend:[15,35],order:[{name:`Hainanese pork chop`,note:`Breaded fried pork chop with potatoes and peas in a Worcestershire-style gravy`},{name:`Roti babi`,note:`Fried bread roll stuffed with minced pork and onion, served with Worcestershire sauce`},{name:`Roast pork (weekends)`,note:`Slow-roasted pork, served only on weekends`}],why:`Family-run Hainanese kopitiam in business since 1928, known for its pork chop, roti babi, kaya toast and butter cake.`,tip:`Breakfast and lunch only; closed Mondays. Near Dang Wangi LRT.`,praise:[`Old-world kopitiam atmosphere`,`Crisp pork chop in a tangy gravy`,`Homely Hainanese classics`],watchOut:`Busy at weekends, and popular items like roast pork can run out.`,reservation:`walk-in`,reservationNote:`No bookings; expect a short wait for a table on weekend mornings`},{id:`sun-fong-bak-kut-teh`,name:`Sun Fong Bak Kut Teh`,localName:`新峰肉骨茶`,area:`Imbi, Bukit Bintang`,lat:3.14459,lng:101.71481,kind:`casual`,meals:[`breakfast`,`lunch`,`dinner`],spend:[20,40],order:[{name:`Herbal bak kut teh in claypot`,price:20,note:`Pork ribs and cuts simmered in a peppery, herbal broth, served in a claypot`,wiki:`Bak kut teh`},{name:`Dry bak kut teh`,price:25,note:`Pork braised down with dried chilli, cuttlefish and dark soy until thick`,wiki:`Bak kut teh`}],why:`Well-known bak kut teh shop off Jalan Imbi serving a strong herbal pork-rib broth and a rich dry version.`,tip:`Non-halal. A short walk from Bukit Bintang and Berjaya Times Square.`,praise:[`Deep, herbal broth`,`Tender pork ribs`,`Dry version with a rich, sticky sauce`],reservation:`walk-in`,reservationNote:`No bookings needed; just turn up and take a table`},{id:`sri-nirwana-maju`,name:`Sri Nirwana Maju`,area:`Bangsar`,lat:3.13106,lng:101.67098,kind:`casual`,meals:[`lunch`,`dinner`,`late`],spend:[12,30],order:[{name:`Banana leaf rice set`,price:10,note:`Rice on a banana leaf with vegetables, poppadoms and a choice of curries`},{name:`Fried chicken`,price:8,note:`Spiced, deep-fried chicken pieces`},{name:`Bitter gourd fritters`,price:5,note:`Thin slices of bitter gourd fried in a spiced batter`}],why:`Bangsar institution for South Indian banana leaf rice, piled with curries, vegetables and crisp fried sides.`,tip:`Expect a queue at weekday lunchtime.`,praise:[`Unlimited rice and vegetable sides`,`Crispy fried chicken`,`Generous curry pours`],watchOut:`Hectic at peak times; it is a no-frills, open-air setting.`,reservation:`walk-in`,reservationNote:`No bookings; walk in and wait for a free table at peak lunch`},{id:`kim-lian-kee`,name:`Kim Lian Kee`,localName:`金莲记`,area:`Petaling Street, Chinatown`,lat:3.14434,lng:101.6975,kind:`casual`,meals:[`dinner`,`late`],spend:[15,30],order:[{name:`KL Hokkien mee`,localName:`福建面`,price:14,note:`Thick yellow noodles braised in dark soy with pork, prawns and crispy lard`,wiki:`Hokkien mee`},{name:`Fried rice noodles (Cantonese style)`,price:14,note:`Wide rice noodles in a silky egg gravy with seafood and meat`}],why:`Petaling Street shop dating back to the late 1920s, credited with creating KL-style Hokkien mee fried over charcoal.`,tip:`Opens around 5pm and runs into the small hours.`,praise:[`Smoky charcoal wok flavour`,`Thick noodles in a glossy dark sauce`,`Crispy pork lard bits`],watchOut:`Can be crowded and touristy, and prices are higher than at nearby stalls.`,reservation:`walk-in`,reservationNote:`No bookings; turn up and wait for a table, shorter waits later at night`},{id:`wong-ah-wah`,name:`Wong Ah Wah (W.A.W.)`,localName:`黄亚华`,area:`Jalan Alor, Bukit Bintang`,lat:3.1449,lng:101.70794,kind:`street`,meals:[`dinner`,`late`],spend:[25,50],order:[{name:`Charcoal-grilled chicken wings`,price:4,note:`Marinated chicken wings grilled over charcoal until caramelised`},{name:`Satay`,price:2,note:`Grilled meat skewers with peanut sauce`,wiki:`Satay`},{name:`Fried kway teow`,note:`Flat rice noodles stir-fried in dark soy with egg and seafood`,wiki:`Char kway teow`}],why:`The best-known restaurant on the Jalan Alor food street, famous for its sticky, smoky grilled chicken wings.`,tip:`Evenings only; wings are priced per piece.`,praise:[`Sticky, sweet, smoky chicken wings`,`Buzzing street atmosphere on Jalan Alor`,`Big menu for groups`],watchOut:`Busy, noisy and touristy; some dishes are pricier than elsewhere.`,reservation:`walk-in`,reservationNote:`No bookings; walk up and take the next free table on the street`},{id:`madam-kwans-klcc`,name:`Madam Kwan’s (Suria KLCC)`,area:`KLCC`,lat:3.15676,lng:101.71197,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[35,70],order:[{name:`Nasi lemak with chicken curry`,note:`Coconut rice with sambal, anchovies, peanuts, egg and chicken curry`,wiki:`Nasi lemak`},{name:`Nasi bojari`,note:`Rice in three colours served with an assortment of meat and sambal dishes`},{name:`Cendol`,note:`Shaved ice with green rice-flour jelly, coconut milk and palm sugar`,wiki:`Cendol`}],why:`Comfortable local chain serving classic Malaysian dishes; the KLCC branch is handy for a sit-down meal near the Petronas Towers.`,tip:`Portions are generous; a good option when it is too hot for street food.`,praise:[`Reliable versions of Malaysian classics`,`Air-conditioned comfort in the mall`,`Large portions`],watchOut:`Pricier than street food for similar dishes.`,reservation:`walk-in`,reservationNote:`Walk-ins usually fine; phone ahead for big groups at weekend dinner`},{id:`dewakan`,name:`Dewakan`,area:`KLCC`,lat:3.15472,lng:101.7185,kind:`fine`,meals:[`dinner`],spend:[700,1e3],order:[{name:`Tasting menu`,note:`A multi-course seasonal menu built on Malaysian produce`}],why:`Chef Darren Teoh’s tasting menus built on Malaysian produce and foraged ingredients; holds two Michelin stars in the 2026 guide.`,tip:`Book weeks ahead; high up in Naza Tower at Platinum Park.`,praise:[`Creative use of local Malaysian ingredients`,`Long, inventive tasting menu`,`City views from high up`],watchOut:`Very expensive; dinner is a set tasting menu only.`,reservation:`essential`,reservationNote:`Book online several weeks ahead; weekend dinners go first`}],dishes:{"Nasi Lemak":{price:[3,15],wiki:`Nasi lemak`},"Roti Canai":{price:[2,5],wiki:`Roti canai`},"Bak Kut Teh":{price:[15,30],wiki:`Bak kut teh`},"KL Hokkien Mee":{price:[12,20],wiki:`Hokkien mee`},Satay:{price:[10,20],wiki:`Satay`},"Banana Leaf Rice":{price:[10,20]}}},penang:{eateries:[{id:`toh-soon-cafe`,name:`Toh Soon Cafe`,localName:`多春茶室`,area:`Campbell Street, George Town`,lat:5.41883,lng:100.33209,kind:`cafe`,meals:[`breakfast`,`lunch`],spend:[6,12],order:[{name:`Charcoal-toasted bread with kaya and butter`,price:3,note:`Bread toasted over charcoal and spread with coconut kaya jam and butter`,wiki:`Kaya toast`},{name:`Soft-boiled eggs`,price:3,note:`Runny eggs eaten with soy sauce and white pepper`},{name:`Kopi`,price:2,note:`Strong local coffee, usually with condensed milk`}],why:`Alley kopitiam off Campbell Street running since the 1950s, toasting bread over charcoal a few slices at a time.`,tip:`Closed Sundays. Toast comes out slowly, so expect to wait at peak breakfast.`,praise:[`Smoky charcoal-toasted bread`,`Atmospheric alleyway seating`,`Cheap, classic kopitiam breakfast`],watchOut:`Hot and crowded in the alley at peak hours, with no air-con.`,reservation:`walk-in`,reservationNote:`No bookings; grab any free stool in the alley and order`},{id:`siam-road-char-koay-teow`,name:`Siam Road Charcoal Char Koay Teow`,localName:`暹罗路炭炒粿条`,area:`Jalan Siam, George Town`,lat:5.41483,lng:100.32098,kind:`street`,meals:[`lunch`,`dinner`],spend:[8,15],order:[{name:`Char koay teow with prawns and cockles`,localName:`炒粿条`,price:9,note:`Flat rice noodles fried over charcoal with prawns, cockles, egg and bean sprouts`,wiki:`Char kway teow`}],why:`Decades-old stall frying each plate over charcoal, now run by the founder’s son; one of Penang’s most famous char koay teow.`,tip:`Waits of 20+ minutes; usually closed Sun–Mon and hours vary, so check before you go.`,praise:[`Strong charcoal smokiness`,`Moist noodles, not greasy`,`Plump prawns`],reservation:`walk-in`,reservationNote:`No bookings; order at the stall, take a seat and wait for your plate`},{id:`penang-road-teochew-chendul`,name:`Penang Road Famous Teochew Chendul`,localName:`潮州煎蕊`,area:`Lebuh Keng Kwee, George Town`,lat:5.41714,lng:100.33067,kind:`dessert`,meals:[`lunch`,`dinner`],spend:[3,8],order:[{name:`Cendol`,price:4,note:`Shaved ice with green pandan jelly, red beans, coconut milk and palm sugar`,wiki:`Cendol`},{name:`Ais kacang`,price:5,note:`Shaved ice with beans, jelly, corn and syrups`,wiki:`Ais kacang`}],why:`Family-run cendol stall on the lane off Penang Road since the 1930s; shaved ice, pandan jelly, coconut milk and palm sugar.`,tip:`Mid-afternoon is peak queue time; it moves fast.`,praise:[`Fragrant coconut milk and palm sugar`,`Refreshing in the afternoon heat`,`Fast-moving queue`],watchOut:`Mostly standing room in the lane, and queues build at peak times.`,reservation:`walk-in`,reservationNote:`No bookings; join the queue at the stall`},{id:`nasi-kandar-line-clear`,name:`Nasi Kandar Line Clear`,area:`Penang Road, George Town`,lat:5.41959,lng:100.33253,kind:`casual`,meals:[`lunch`,`dinner`,`late`],spend:[10,25],order:[{name:`Nasi kandar with fried chicken, curries mixed`,price:15,note:`Steamed rice with fried chicken, flooded with several curry gravies`,wiki:`Nasi kandar`},{name:`Fried squid`,price:8,note:`Squid fried in a spiced batter or sauce`}],why:`Alleyway nasi kandar stall serving rice flooded with curries since the 1930s; a round-the-clock Penang staple.`,tip:`Ask for "kuah campur" to get mixed curry gravies over your rice.`,praise:[`Rich, flavourful mixed curries`,`Open almost round the clock`,`Satisfying late-night meal`],watchOut:`Prices are by the item and can add up; ask before you load your plate.`,reservation:`walk-in`,reservationNote:`No bookings; queue, point at what you want, then find a seat`},{id:`888-hokkien-mee`,name:`888 Hokkien Mee`,localName:`888福建虾面`,area:`Lebuh Presgrave, George Town`,lat:5.4111,lng:100.33064,kind:`hawker`,meals:[`lunch`,`dinner`],spend:[8,15],order:[{name:`Prawn Hokkien mee`,localName:`福建虾面`,price:9,note:`Noodles in a spicy prawn and pork broth with prawns, egg and kangkung`,wiki:`Hokkien mee`},{name:`Add roast pork`,price:4,note:`Extra slices of crisp-skinned roast pork for your bowl`}],why:`Corner coffee-shop stall that has served deep red prawn-broth Hokkien mee for about 30 years.`,tip:`Opens mid-afternoon, closed Thursdays; arrive before 6pm and it can sell out.`,praise:[`Rich, sweet prawn-shell broth`,`Lots of toppings for the price`,`Optional extras like pork ribs and roast pork`],watchOut:`Can sell out early, and the open coffee shop gets hot.`,reservation:`walk-in`,reservationNote:`Hawker stall: no bookings; find a table in the coffee shop and order`},{id:`auntie-gaik-leans`,name:`Auntie Gaik Lean’s Old School Eatery`,area:`Bishop Street, George Town`,lat:5.418,lng:100.34239,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[80,150],order:[{name:`Jiu hu char (stir-fried jicama with cuttlefish)`,note:`Shredded jicama stir-fried with dried cuttlefish, eaten wrapped in lettuce`},{name:`Perut ikan`,note:`Spicy, sour Nyonya curry of fish stomach and herbs`},{name:`Nasi ulam`,note:`Rice tossed with finely shredded fresh herbs`}],why:`Home-style Nyonya cooking in a heritage shophouse; kept its Michelin star in the 2026 guide.`,tip:`Book ahead, especially for dinner.`,praise:[`Home-style Nyonya flavours`,`Heritage shophouse setting`,`Good dishes for sharing`],watchOut:`Hard to get a table without booking.`,reservation:`essential`,reservationNote:`Book by phone or online a few days ahead; dinner slots fill first`},{id:`air-itam-laksa`,name:`Penang Air Itam Laksa`,localName:`亚依淡叻沙`,area:`Air Itam Market`,lat:5.4013,lng:100.27795,kind:`hawker`,meals:[`lunch`,`dinner`],spend:[6,10],order:[{name:`Assam laksa`,price:7,note:`Rice noodles in a sour tamarind and mackerel broth with mint, pineapple and prawn paste`,wiki:`Laksa`}],why:`Decades-old stall by Air Itam market, a short walk from Kek Lok Si temple; sour, spicy mackerel-tamarind broth.`,tip:`Pair it with a visit to Kek Lok Si; the stall is now run by the late founder’s family.`,praise:[`Tangy, spicy fish broth`,`Generous flaked mackerel`,`Pairs well with a Kek Lok Si visit`],watchOut:`Basic roadside seating, hot in the afternoon.`,reservation:`walk-in`,reservationNote:`Hawker stall: no bookings; walk up and order`},{id:`gurney-drive-hawker-centre`,name:`Gurney Drive Hawker Centre`,localName:`新关仔角夜市`,area:`Gurney Drive`,lat:5.43981,lng:100.30913,kind:`hawker`,meals:[`dinner`,`late`],spend:[10,30],order:[{name:`Oyster omelette`,localName:`蚝煎`,price:15,note:`Small oysters fried with egg and starch until crisp at the edges`,wiki:`Oyster omelette`},{name:`Rojak`,price:8,note:`Fruit and vegetable salad in a thick, sweet prawn-paste sauce`,wiki:`Rojak`},{name:`Char koay teow`,price:10,note:`Flat rice noodles fried with prawns, cockles and egg`,wiki:`Char kway teow`}],why:`Penang’s best-known seafront hawker centre, with dozens of evening stalls covering most island classics.`,tip:`Evenings only and packed at weekends. Planned move to a new Gurney Bay site around 2027.`,praise:[`Wide choice of Penang dishes in one place`,`Breezy seafront location`,`Lively evening atmosphere`],watchOut:`Prices are higher than at neighbourhood hawkers, and it is very busy at weekends.`,reservation:`walk-in`,reservationNote:`No bookings; find a free table first, then order from the stalls`}],dishes:{"Penang Char Kway Teow":{price:[8,15],wiki:`Char kway teow`},"Penang Assam Laksa":{price:[6,10],wiki:`Laksa`},"Nasi Kandar":{price:[10,25],wiki:`Nasi kandar`},"Penang Hokkien Mee":{price:[8,15],wiki:`Hokkien mee`},Cendol:{price:[3,6],wiki:`Cendol`},"Oyster Omelette":{price:[12,25],wiki:`Oyster omelette`}}}};export{a,s as i,d as n,r as o,l as r,t as s,p as t};